{
  "name": "dep-resolver",
  "type": "module",
  "private": true,
  "scripts": {
    "test": "node --test test/*.test.js"
  }
}
---
/**
 * Public surface of the dependency resolver.
 */
export { ResolveError, compareVersions, maxSatisfying, parseRange, parseVersion, satisfies } from './semver.js';
export { ConflictError, resolve } from './resolve.js';
---
/**
 * A small semantic-version dialect: three numeric parts, and ranges built from
 * comparators, carets and tildes.
 *
 * Parsing and ordering of plain versions work; ranges do not exist yet.
 */

/** Error raised for malformed versions, ranges, registries and unsatisfiable graphs. */
export class ResolveError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'ResolveError';
    this.code = code;
  }
}

const VERSION_PATTERN = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/;

/**
 * Parse a version string.
 *
 * @param {string} text Version to parse.
 * @returns {{major: number, minor: number, patch: number}} Parsed parts.
 */
export function parseVersion(text) {
  const match = typeof text === 'string' ? VERSION_PATTERN.exec(text) : null;
  if (match === null) throw new ResolveError('BAD_VERSION', `invalid version: ${text}`);
  return { major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]) };
}

/**
 * Order two versions.
 *
 * @param {string} left First version.
 * @param {string} right Second version.
 * @returns {-1|0|1} Comparison result.
 */
export function compareVersions(left, right) {
  const a = parseVersion(left);
  const b = parseVersion(right);
  for (const part of ['major', 'minor', 'patch']) {
    if (a[part] !== b[part]) return a[part] < b[part] ? -1 : 1;
  }
  return 0;
}

/**
 * Parse a range into comparators that must all hold.
 *
 * @param {string} text Range to parse.
 * @returns {Array<{operator: string, version: string}>} Comparators, empty for `*`.
 */
export function parseRange(text) {
  throw new Error('not implemented');
}

/**
 * Test a version against a range.
 *
 * @param {string} version Version to test.
 * @param {string} range Range to test against.
 * @returns {boolean} True when every comparator holds.
 */
export function satisfies(version, range) {
  throw new Error('not implemented');
}

/**
 * Highest version of a list that satisfies a range.
 *
 * @param {string[]} versions Candidate versions.
 * @param {string} range Range to satisfy.
 * @returns {string|null} The highest match, or null.
 */
export function maxSatisfying(versions, range) {
  throw new Error('not implemented');
}
---
/**
 * Flat dependency resolution over an in-memory registry: one version per
 * package, chosen highest-first, with a conflict report naming the chain that
 * imposed each constraint.
 */
import { ResolveError } from './semver.js';

/** Raised when no version of a package satisfies everything asked of it. */
export class ConflictError extends ResolveError {
  /**
   * @param {string} packageName Package that could not be satisfied.
   * @param {Array<{range: string, via: string}>} constraints Every constraint on it, in the order they arrived.
   * @param {string[]} available Versions the registry offers, ascending.
   */
  constructor(packageName, constraints, available) {
    const detail = constraints.map((entry) => `${entry.range} (from ${entry.via})`).join(', ');
    super('CONFLICT', `cannot satisfy ${packageName}: ${detail}`);
    this.name = 'ConflictError';
    this.packageName = packageName;
    this.constraints = constraints;
    this.available = available;
  }
}

/**
 * Resolve one version per package.
 *
 * @param {Record<string, Record<string, {deps?: Record<string, string>}>>} registry Available packages.
 * @param {Record<string, string>} rootDeps Ranges the root asks for.
 * @returns {{resolved: Record<string, string>, order: string[]}} Selection and the order it was made in.
 */
export function resolve(registry, rootDeps) {
  throw new Error('not implemented');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { ResolveError, compareVersions, maxSatisfying, parseRange, parseVersion, satisfies } from '../src/index.js';

test('parseVersion accepts three numeric parts and nothing else', () => {
  assert.deepEqual(parseVersion('1.2.3'), { major: 1, minor: 2, patch: 3 });
  assert.deepEqual(parseVersion('0.0.0'), { major: 0, minor: 0, patch: 0 });
  assert.deepEqual(parseVersion('10.20.30'), { major: 10, minor: 20, patch: 30 });
  for (const bad of ['1.2', '1.2.3.4', 'v1.2.3', '01.2.3', '1.02.3', '1.2.3-beta', '', ' 1.2.3', '1.2.x', 5, null]) {
    assert.throws(() => parseVersion(bad), { name: 'ResolveError', code: 'BAD_VERSION' }, `parseVersion(${bad})`);
  }
  assert.equal(new ResolveError('X', 'y') instanceof Error, true);
});

test('compareVersions orders numerically, not lexically', () => {
  assert.equal(compareVersions('1.9.0', '1.10.0'), -1);
  assert.equal(compareVersions('1.10.0', '1.9.0'), 1);
  assert.equal(compareVersions('2.0.0', '10.0.0'), -1);
  assert.equal(compareVersions('1.2.3', '1.2.3'), 0);
  assert.equal(compareVersions('1.2.10', '1.2.9'), 1);
  assert.equal(compareVersions('0.0.1', '0.1.0'), -1);
  assert.deepEqual(['1.10.0', '1.2.0', '1.9.0'].sort(compareVersions), ['1.2.0', '1.9.0', '1.10.0']);
});

test('parseRange expands carets and tildes into comparators', () => {
  assert.deepEqual(parseRange('*'), []);
  assert.deepEqual(parseRange('1.2.3'), [{ operator: '=', version: '1.2.3' }]);
  assert.deepEqual(parseRange('=1.2.3'), [{ operator: '=', version: '1.2.3' }]);
  assert.deepEqual(parseRange('^1.2.3'), [
    { operator: '>=', version: '1.2.3' },
    { operator: '<', version: '2.0.0' },
  ]);
  assert.deepEqual(parseRange('^0.2.3'), [
    { operator: '>=', version: '0.2.3' },
    { operator: '<', version: '0.3.0' },
  ]);
  assert.deepEqual(parseRange('^0.0.3'), [
    { operator: '>=', version: '0.0.3' },
    { operator: '<', version: '0.0.4' },
  ]);
  assert.deepEqual(parseRange('~1.2.3'), [
    { operator: '>=', version: '1.2.3' },
    { operator: '<', version: '1.3.0' },
  ]);
  assert.deepEqual(parseRange('>=1.0.0 <2.0.0'), [
    { operator: '>=', version: '1.0.0' },
    { operator: '<', version: '2.0.0' },
  ]);
  assert.deepEqual(parseRange('  >1.0.0   <=2.0.0  '), [
    { operator: '>', version: '1.0.0' },
    { operator: '<=', version: '2.0.0' },
  ]);
});

test('parseRange rejects malformed ranges', () => {
  for (const bad of ['', '   ', '^1.2', '1.2.3.4', '>=', '>= 1.0.0', 'x', '* 1.0.0', '1.0.0 *', '^', '~', 'v1.0.0', 7]) {
    assert.throws(() => parseRange(bad), { name: 'ResolveError', code: 'BAD_RANGE' }, `parseRange(${bad})`);
  }
});

test('satisfies honours every boundary', () => {
  const cases = [
    ['1.2.3', '*', true],
    ['0.0.0', '*', true],
    ['1.2.3', '1.2.3', true],
    ['1.2.4', '1.2.3', false],
    ['1.2.3', '^1.2.3', true],
    ['1.9.9', '^1.2.3', true],
    ['1.2.2', '^1.2.3', false],
    ['2.0.0', '^1.2.3', false],
    ['1.0.0', '^1.0.0', true],
    ['0.2.3', '^0.2.3', true],
    ['0.2.9', '^0.2.3', true],
    ['0.3.0', '^0.2.3', false],
    ['0.2.2', '^0.2.3', false],
    ['0.0.3', '^0.0.3', true],
    ['0.0.4', '^0.0.3', false],
    ['1.2.3', '~1.2.3', true],
    ['1.2.99', '~1.2.3', true],
    ['1.3.0', '~1.2.3', false],
    ['1.2.2', '~1.2.3', false],
    ['1.5.0', '>=1.0.0 <2.0.0', true],
    ['2.0.0', '>=1.0.0 <2.0.0', false],
    ['1.0.0', '>=1.0.0 <2.0.0', true],
    ['1.0.0', '>1.0.0', false],
    ['1.0.1', '>1.0.0', true],
    ['2.0.0', '<=2.0.0', true],
    ['2.0.1', '<=2.0.0', false],
    ['1.10.0', '<1.9.0', false],
    ['1.9.0', '<1.10.0', true],
  ];
  for (const [version, range, expected] of cases) {
    assert.equal(satisfies(version, range), expected, `${version} vs ${range}`);
  }
  assert.throws(() => satisfies('1.2', '*'), { code: 'BAD_VERSION' });
  assert.throws(() => satisfies('1.2.3', 'nope'), { code: 'BAD_RANGE' });
});

test('maxSatisfying picks the highest match', () => {
  const versions = ['1.0.0', '1.10.0', '1.9.0', '2.0.0', '0.9.0'];
  assert.equal(maxSatisfying(versions, '*'), '2.0.0');
  assert.equal(maxSatisfying(versions, '^1.0.0'), '1.10.0');
  assert.equal(maxSatisfying(versions, '~1.9.0'), '1.9.0');
  assert.equal(maxSatisfying(versions, '<1.0.0'), '0.9.0');
  assert.equal(maxSatisfying(versions, '>=3.0.0'), null);
  assert.equal(maxSatisfying([], '*'), null);
  assert.equal(maxSatisfying(['1.2.3'], '1.2.3'), '1.2.3');
  assert.throws(() => maxSatisfying('1.0.0', '*'), { code: 'BAD_VERSION' });
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { ConflictError, ResolveError, resolve, satisfies } from '../src/index.js';

/** Deterministic 32-bit PRNG so generated registries replay identically. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const chain = {
  a: {
    '1.0.0': { deps: { b: '^1.0.0' } },
    '1.2.0': { deps: { b: '^1.0.0' } },
    '2.0.0': { deps: { b: '^2.0.0' } },
  },
  b: { '1.0.0': {}, '1.5.0': {}, '2.0.0': {} },
};

test('resolution takes the highest satisfying version of each package', () => {
  assert.deepEqual(resolve(chain, { a: '^1.0.0' }), {
    resolved: { a: '1.2.0', b: '1.5.0' },
    order: ['a', 'b'],
  });
  assert.deepEqual(resolve(chain, { a: '*' }), {
    resolved: { a: '2.0.0', b: '2.0.0' },
    order: ['a', 'b'],
  });
  assert.deepEqual(resolve(chain, {}), { resolved: {}, order: [] });
  assert.deepEqual(resolve({ p: { '1.0.0': {}, '1.10.0': {}, '1.9.0': {} } }, { p: '^1.0.0' }).resolved, {
    p: '1.10.0',
  });
});

test('constraints from several requirers narrow one choice', () => {
  const registry = {
    left: { '1.0.0': { deps: { shared: '<2.0.0' } } },
    right: { '1.0.0': { deps: { shared: '>=1.5.0' } } },
    shared: { '1.0.0': {}, '1.5.0': {}, '1.9.0': {}, '2.0.0': {} },
  };
  const result = resolve(registry, { left: '*', right: '*' });
  assert.deepEqual(result.resolved, { left: '1.0.0', right: '1.0.0', shared: '1.9.0' });
  assert.deepEqual(result.order, ['left', 'right', 'shared']);
});

test('packages are visited in a fixed order', () => {
  const registry = {
    apple: { '1.0.0': {} },
    zebra: { '1.0.0': { deps: { mango: '*' } } },
    mango: { '1.0.0': {} },
  };
  const result = resolve(registry, { zebra: '*', apple: '*' });
  assert.deepEqual(result.order, ['apple', 'zebra', 'mango']);
  assert.deepEqual(Object.keys(result.resolved), ['apple', 'mango', 'zebra']);
});

test('a cycle resolves once every package is chosen', () => {
  const registry = {
    ping: { '1.0.0': { deps: { pong: '^1.0.0' } } },
    pong: { '1.0.0': { deps: { ping: '^1.0.0' } } },
  };
  assert.deepEqual(resolve(registry, { ping: '*' }), {
    resolved: { ping: '1.0.0', pong: '1.0.0' },
    order: ['ping', 'pong'],
  });
});

test('an unsatisfiable root constraint names the root', () => {
  const registry = { solo: { '1.0.0': {}, '2.0.0': {} } };
  assert.throws(
    () => resolve(registry, { solo: '>=3.0.0' }),
    (error) => {
      assert.equal(error instanceof ConflictError, true);
      assert.equal(error instanceof ResolveError, true);
      assert.equal(error.name, 'ConflictError');
      assert.equal(error.code, 'CONFLICT');
      assert.equal(error.packageName, 'solo');
      assert.deepEqual(error.constraints, [{ range: '>=3.0.0', via: '<root>' }]);
      assert.deepEqual(error.available, ['1.0.0', '2.0.0']);
      assert.equal(error.message, 'cannot satisfy solo: >=3.0.0 (from <root>)');
      return true;
    },
  );
});

test('a conflict between two requirers lists both chains', () => {
  const registry = {
    alpha: { '1.0.0': { deps: { core: '<2.0.0' } } },
    zeta: { '1.0.0': { deps: { core: '>=2.0.0' } } },
    core: { '1.0.0': {}, '1.9.0': {}, '2.0.0': {} },
  };
  assert.throws(
    () => resolve(registry, { alpha: '*', zeta: '*' }),
    (error) => {
      assert.equal(error.packageName, 'core');
      assert.deepEqual(error.constraints, [
        { range: '<2.0.0', via: '<root> > alpha@1.0.0' },
        { range: '>=2.0.0', via: '<root> > zeta@1.0.0' },
      ]);
      assert.equal(
        error.message,
        'cannot satisfy core: <2.0.0 (from <root> > alpha@1.0.0), >=2.0.0 (from <root> > zeta@1.0.0)',
      );
      return true;
    },
  );
});

test('a deep conflict names the whole chain that asked for it', () => {
  const registry = {
    top: { '1.0.0': { deps: { mid: '^1.0.0' } } },
    mid: { '1.0.0': { deps: { leaf: '>=5.0.0' } } },
    leaf: { '1.0.0': {}, '2.0.0': {} },
  };
  assert.throws(
    () => resolve(registry, { top: '^1.0.0' }),
    (error) => {
      assert.equal(error.packageName, 'leaf');
      assert.deepEqual(error.constraints, [{ range: '>=5.0.0', via: '<root> > top@1.0.0 > mid@1.0.0' }]);
      assert.equal(error.message, 'cannot satisfy leaf: >=5.0.0 (from <root> > top@1.0.0 > mid@1.0.0)');
      return true;
    },
  );
});

test('missing packages are reported before anything else fails', () => {
  assert.throws(() => resolve({}, { ghost: '*' }), {
    name: 'ResolveError',
    code: 'UNKNOWN_PACKAGE',
    message: 'unknown package: ghost',
  });
  assert.throws(() => resolve({ a: { '1.0.0': { deps: { missing: '*' } } } }, { a: '*' }), {
    code: 'UNKNOWN_PACKAGE',
    message: 'unknown package: missing',
  });
  assert.throws(() => resolve({ empty: {} }, { empty: '*' }), { code: 'CONFLICT' });
});

test('the registry and the root dependencies are validated', () => {
  assert.throws(() => resolve(null, {}), { code: 'BAD_REGISTRY', message: 'registry must be an object' });
  assert.throws(() => resolve([], {}), { code: 'BAD_REGISTRY' });
  assert.throws(() => resolve({ a: 'nope' }, {}), {
    code: 'BAD_REGISTRY',
    message: 'registry entry must be an object: a',
  });
  assert.throws(() => resolve({ a: { '1.x': {} } }, {}), { code: 'BAD_VERSION' });
  assert.throws(() => resolve({ a: { '1.0.0': null } }, {}), {
    code: 'BAD_REGISTRY',
    message: 'metadata must be an object: a@1.0.0',
  });
  assert.throws(() => resolve({ a: { '1.0.0': { deps: 'x' } } }, {}), { code: 'BAD_DEPENDENCIES' });
  assert.throws(() => resolve({ a: { '1.0.0': { deps: { b: 'bad' } } } }, {}), { code: 'BAD_RANGE' });
  assert.throws(() => resolve({}, null), {
    code: 'BAD_DEPENDENCIES',
    message: 'root dependencies must be an object',
  });
  assert.throws(() => resolve({}, { a: '^' }), { code: 'BAD_RANGE' });
});

test('every successful resolution satisfies every constraint it collected', () => {
  const pick = mulberry32(606060);
  const names = ['p0', 'p1', 'p2', 'p3', 'p4', 'p5'];
  const versions = ['1.0.0', '1.1.0', '1.2.0', '1.4.0', '2.0.0'];
  const ranges = ['*', '^1.0.0', '>=1.2.0', '~1.1.0', '<1.4.0', '^2.0.0'];
  let successes = 0;
  let conflicts = 0;
  for (let round = 0; round < 200; round += 1) {
    const registry = {};
    names.forEach((name, index) => {
      registry[name] = {};
      for (const version of versions) {
        if (pick() < 0.35) continue;
        const deps = {};
        for (const other of names.slice(index + 1)) {
          if (pick() < 0.3) deps[other] = ranges[Math.floor(pick() * ranges.length)];
        }
        registry[name][version] = { deps };
      }
      if (Object.keys(registry[name]).length === 0) registry[name]['1.0.0'] = { deps: {} };
    });
    const rootDeps = {};
    for (const name of names) {
      if (pick() < 0.5) rootDeps[name] = ranges[Math.floor(pick() * ranges.length)];
    }

    let result;
    try {
      result = resolve(registry, rootDeps);
    } catch (error) {
      conflicts += 1;
      assert.equal(error.code, 'CONFLICT', `round ${round} failed for the expected reason`);
      assert.ok(error.constraints.length >= 1, 'a conflict always cites a constraint');
      assert.ok(error.message.startsWith(`cannot satisfy ${error.packageName}: `), 'the message names the package');
      continue;
    }
    successes += 1;
    assert.deepEqual(Object.keys(result.resolved), [...Object.keys(result.resolved)].sort(), 'keys are ordered');
    assert.deepEqual([...result.order].sort(), Object.keys(result.resolved), 'order lists exactly what was resolved');
    assert.equal(new Set(result.order).size, result.order.length, 'nothing is selected twice');
    for (const [name, range] of Object.entries(rootDeps)) {
      assert.ok(satisfies(result.resolved[name], range), `root ${name} ${range} is satisfied`);
    }
    for (const [name, version] of Object.entries(result.resolved)) {
      const deps = registry[name][version].deps ?? {};
      for (const [dep, range] of Object.entries(deps)) {
        assert.ok(result.resolved[dep] !== undefined, `${dep} required by ${name} was selected`);
        assert.ok(satisfies(result.resolved[dep], range), `${name}@${version} needs ${dep} ${range}`);
      }
    }
  }
  assert.ok(successes > 20, `enough registries resolved (${successes})`);
  assert.ok(conflicts > 5, `enough registries conflicted (${conflicts})`);
});

