const VERSION_PATTERN = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/;

/**
 * Parse a version string.
 *
 * @param {string} text Version to parse.
 * @returns {{major: number, minor: number, patch: number}} Parsed parts.
 */
export function parseVersion(text) {
  const match = typeof text === 'string' ? VERSION_PATTERN.exec(text) : null;
  if (match === null) throw new ResolveError('BAD_VERSION', `invalid version: ${text}`);
  return { major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]) };
}

/**
 * Order two versions.
 *
 * @param {string} left First version.
 * @param {string} right Second version.
 * @returns {-1|0|1} Comparison result.
 */
export function compareVersions(left, right) {
  const a = parseVersion(left);
  const b = parseVersion(right);
  for (const part of ['major', 'minor', 'patch']) {
    if (a[part] !== b[part]) return a[part] < b[part] ? -1 : 1;
  }
  return 0;
}

const OPERATORS = ['>=', '<=', '>', '<', '='];

/**
 * Parse a single range token into one or more comparators.
 *
 * @param {string} token Whitespace-free token.
 * @param {string} original Full range text, for error messages.
 * @returns {Array<{operator: string, version: string}>} Comparators.
 */
function parseToken(token, original) {
  try {
    if (token.startsWith('^')) {
      const version = token.slice(1);
      const { major, minor, patch } = parseVersion(version);
      let upper;
      if (major !== 0) upper = `${major + 1}.0.0`;
      else if (minor !== 0) upper = `${major}.${minor + 1}.0`;
      else upper = `${major}.${minor}.${patch + 1}`;
      return [
        { operator: '>=', version },
        { operator: '<', version: upper },
      ];
    }
    if (token.startsWith('~')) {
      const version = token.slice(1);
      const { major, minor } = parseVersion(version);
      const upper = `${major}.${minor + 1}.0`;
      return [
        { operator: '>=', version },
        { operator: '<', version: upper },
      ];
    }
    for (const operator of OPERATORS) {
      if (token.startsWith(operator)) {
        const version = token.slice(operator.length);
        parseVersion(version);
        return [{ operator, version }];
      }
    }
    parseVersion(token);
    return [{ operator: '=', version: token }];
  } catch {
    throw new ResolveError('BAD_RANGE', `invalid range: ${original}`);
  }
}

/**
 * Parse a range into comparators that must all hold.
 *
 * @param {string} text Range to parse.
 * @returns {Array<{operator: string, version: string}>} Comparators, empty for `*`.
 */
export function parseRange(text) {
  if (typeof text !== 'string') throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  const trimmed = text.trim();
  if (trimmed === '') throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  if (trimmed === '*') return [];
  const tokens = trimmed.split(/\s+/);
  if (tokens.includes('*')) throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  const comparators = [];
  for (const token of tokens) {
    comparators.push(...parseToken(token, text));
  }
  return comparators;
