  const rootNames = Object.keys(rootDeps).sort();
  for (const name of rootNames) {
    if (!constraints[name]) constraints[name] = [];
    constraints[name].push({ range: rootDeps[name], via: '<root>' });
    pending.add(name);
  }

  while (pending.size > 0) {
    const name = [...pending].sort()[0];
    pending.delete(name);

    if (!Object.prototype.hasOwnProperty.call(registry, name)) {
      throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    }

    const entry = registry[name];
    const available = Object.keys(entry).sort(compareVersions);
    const myConstraints = constraints[name] ?? [];

    let best = null;
    for (const version of available) {
      let ok = true;
      for (const { range } of myConstraints) {
        if (!satisfiesRange(version, range)) {
          ok = false;
          break;
        }
      }
      if (ok && (best === null || compareVersions(version, best) > 0)) best = version;
    }

    if (best === null) {
      throw new ConflictError(name, myConstraints, available);
    }

    selected[name] = best;
    order.push(name);

    const originConstraint = myConstraints[0];
    const chain = `${originConstraint.via} > ${name}@${best}`;

    const meta = entry[best];
    const deps = meta.deps ?? {};
    const depNames = Object.keys(deps).sort();
    for (const depName of depNames) {
      const range = deps[depName];
      if (!constraints[depName]) constraints[depName] = [];
      constraints[depName].push({ range, via: chain });

      if (Object.prototype.hasOwnProperty.call(selected, depName)) {
        if (!satisfiesRange(selected[depName], range)) {
          const depAvailable = Object.keys(registry[depName]).sort(compareVersions);
          throw new ConflictError(depName, constraints[depName], depAvailable);
        }
      } else {
        pending.add(depName);
      }
    }
  }

  const resolved = {};
  for (const name of Object.keys(selected).sort()) {
    resolved[name] = selected[name];
  }

  return { resolved, order };
}
